];
const changes=[];
for (let i=1;i<vals.length;i++) changes.push([vals[i][0], (vals[i][1]/vals[i-1][1]-1)*100]);
console.log('monthly percent changes from fetched WDS levels:');
for (const [p,c] of changes) console.log("'`${p} ${c.toFixed(3)}`);
const xs=changes.map(x=>x[1]);
const n=xs.length, mean=xs.reduce((a,b)=>a+b,0)/n;
const sd=Math.sqrt(xs.reduce((a,b)=>a+(b-mean)**2,0)/(n-1));
const sorted=[...xs].sort((a,b)=>a-b);
const q=(p)=>{ const pos=(n-1)*p; const lo=Math.floor(pos), hi=Math.ceil(pos); return lo===hi?sorted[lo]:sorted[lo]+(sorted[hi]-sorted[lo])*(pos-lo); };
const absErr=xs.slice(1).map((x,i)=>x-xs[i]);
const mErr=absErr.reduce((a,b)=>a+b,0)/absErr.length;
const sdErr=Math.sqrt(absErr.reduce((a,b)=>a+(b-mErr)**2,0)/(absErr.length-1));
console.log(`n=${n} mean=${mean.toFixed(3)} sigma_values=${sd.toFixed(3)} p10=${q(0.1).toFixed(3)} p50=${q(0.5).toFixed(3)} p90=${q(0.9).toFixed(3)} min=${sorted[0].toFixed(3)} max=${sorted[n-1].toFixed(3)}`);
console.log(`persistence last_print May 2026 change=${xs[xs.length-1].toFixed(3)}; successive_change_sigma=${sdErr.toFixed(3)} from ${absErr.length} changes; 1.28*sigma=${(1.28*sdErr).toFixed(3)}`);
NODE'

