const changes=[0.199,0.117,0.270,0.414,-0.204,0.202,0.546,-0.155,0.173,-0.091,-0.184,0.017,0.646,-0.054,0.189,-0.258,0.080,0.130,-0.045,0.192,-0.155,0.582,0.340];
